{"understood": "Opening your Downloads folder right up.", "steps": [
 {"do":"action","name":"finder_open","args":{"path":"~/Downloads"}},
 {"do":"expect","element":"Downloads"},
 {"do":"done","say":"Here's your Downloads folder, all open."}
]}

{"understood": "Turning off your Wi-Fi now.",
 "steps": [
   {"do": "action", "name": "wifi", "args": {"on": false}},
   {"do": "done", "say": "Wi-Fi is off."}
 ]}

{"understood": "turning on Do Not Disturb now",
 "steps": [
  {"do":"find","what":"Do Not Disturb","role":"checkbox","then":"press","say":"Do Not Disturb is turned on"},
  {"do":"done","say":"Do Not Disturb is on."}
 ]}

{"understood": "Searching for your iGEM page now.",
 "steps": [
  {"do": "menu", "path": "Cmd + P"},
  {"do": "find", "what": "Search pages", "role": "input", "typeable": true},
  {"do": "key", "combo": "return"},
  {"do": "expect", "element": "iGEM"}
]
}

